public int rentalLengthInDays()
{
    #timeConstants
    int rentalPeriodInDays;
    if (this.StartDate == DateTimeUtil::minValue() ||
        this.EndDate == DateTimeUtil::minValue())
    {
        rentalPeriodInDays = 0;
    }
    else
    {
        rentalPeriodInDays = real2int(roundUp(DateTimeUtil::getDifference(this.EndDate, this.StartDate) / #secondsPerDay, 1));
    }
    return rentalPeriodInDays;
}

public boolean canRelease()
{
    FMVehicle vehicle;
    boolean result = false;

    select firstonly vehicle where vehicle.RecId == this.Vehicle;

    if(vehicle)
    {
        // If vehicle is not available then do not allow the vehicle to be released
        switch (vehicle.Status)
        {
            case FMVehicleStatus::Rented:
                warning('This vehicle is currently being rented. Please choose an available vehicle.');
                break;

            case FMVehicleStatus::Damaged:
            case FMVehicleStatus::Pending:
            case FMVehicleStatus::Recalled:
            case FMVehicleStatus::InService:
                warning('This vehicle is not available. It may be damaged, in service or recalled. Please choose an available vehicle.');
                break;

            case FMVehicleStatus::Available:

                result = true;
                break;

            default:
                error(strfmt("Unknown FMVehicleStatus: %1", vehicle.Status));
                break;
        }
    }
    else
    {
        warning("no vehicle");
    }

    return result;
}

public static FMRental find(FMRentalId _rentalId, boolean _forupdate = false)
{
    FMRental result;

    result.selectForUpdate(_forupdate);
    select firstonly result where result.RentalId == _rentalId;

    return result;
}

public display FMRentalTotal totals()
{
    return FMTotalsEngineBase::GetInstance().totals(this);
}

public display FMRentalTotal savings()
{
    return FMTotalsEngineBase::GetInstance().savings(this);
}

public display FMChargesTotal rentalChargesTotal()
{
    return FMTotalsEngineBase::GetInstance().chargesTotals(this);
}

public void initFromCustomer(FMCustomerRecId _customer = this.Customer)
{
    FMPaymentInformation payment; 
    if (!_customer)
    {
        this.PaymentInformationID = 0; 
    }
    else
    {
        select firstonly payment where payment.CustomerID == _customer;
        this.PaymentInformationID = payment.RecId; 
    }
}

public void initFromVehicle(FMVehicleRecId _vehicle = this.Vehicle)
{
    container rates;
    if (!_vehicle)
    {
        this.VehicleRatePerDay = 0;
        this.VehicleRatePerWeek = 0;
    }
    else
    {
        rates = FMModelRate::getRate(_vehicle);
        if (conlen(rates) >=2)
        {
            this.VehicleRatePerDay = conpeek(rates, 1);
            this.VehicleRatePerWeek = conpeek(rates, 2);
        }
    }
    this.VehicleRateTotal = 0;
}

public void modifiedField(FieldId _fieldId)
{
    super(_fieldId);

    switch (_fieldId)
    {
        case fieldnum(FMRental, Vehicle):
            this.initFromVehicle();
            break;
        case fieldnum(FMRental, StartDate):
        case fieldnum(FMRental, EndDate):
            FMTotalsEngineBase::GetInstance().calculateRentalVehicleRate(this);
            break;
        case fieldnum(FMRental, Customer):
            this.initFromCustomer(); 
            break;
    }
}

public void initValue()
{
    super();

    this.StartDate = DateTimeUtil::utcNow();
}

public display FMDescription rentalVehicle()
{
    FMVehicle vehicle;
    str value;

    if(this.Vehicle == 0)
    {        
        value = "No vehicle assigned"; 
    }
    else
    {
        select vehicle where vehicle.RecId == this.Vehicle;            
        value = vehicle.Description;
    }

    return value;
}

public display str idState()
{
    return this.RentalId + ": " + enum2str(this.State);
}

public display str dateRange()
{
    str sDate = date2str(DateTimeUtil::date(DateTimeUtil::applyTimeZoneOffset(this.StartDate, DateTimeUtil::getUserPreferredTimeZone())), 213, DateDay::Digits2, DateSeparator::Slash, DateMonth::Digits2, DateSeparator::Slash, DateYear::Digits4);
    str eDate = date2str(DateTimeUtil::date(DateTimeUtil::applyTimeZoneOffset(this.EndDate, DateTimeUtil::getUserPreferredTimeZone())), 213, DateDay::Digits2, DateSeparator::Slash, DateMonth::Digits2, DateSeparator::Slash, DateYear::Digits4);

    return sDate + " - " + eDate;
}

public display str customerName()
{
    FMCustomer customer; 
    str value; 

    select customer where customer.RecId == this.Customer; 
    if(customer)
    {
        value = customer.fullName(); 
    }

    return value; 
}

public display container rentalImage()
{
    ImageReference imgRef;
    FMVehicle car; 
    FMVehicleModel model; 
    container imgContainer; 

    //Grab the symbol as the default value
    imgRef = ImageReference::constructForSymbol("CarRental");
    imgContainer = imgRef.pack();      

    //If the rental has a linked vehicle and...
    if(this.Vehicle != 0)
    {
        select car where car.RecId == this.Vehicle; 

        //If the vehicle exists and...
        if(car)
        {
            select model where model.RecId == car.VehicleModel; 

            //If the vehicle model exists and there is an image
            if(model && model.Image != connull())
            {
                //Display that image
                imgContainer = model.Image; 
            }                 
        }
    }

    return imgContainer;
}

public boolean validateWrite()
{
    boolean ret;
    FMRentalCheckoutProcessor rcheck;     

    //call out to the class that raises the event for finalizing rental record.
    //if the eventhandlers havent raised objections then go ahead and call super()
    //else some eventhandler that is registered has vetoed this rental. So just return
    //false.
    rcheck = new FMRentalCheckoutProcessor();

    ret = rcheck.FinalizeRentalCheckout(this);
    if(ret == true)
    {                      
        ret = super();            
    }
    else
    {
        error('Sorry cannot rent a vehicle to this customer. Their driving record is terrible !!!');

    }

    return ret;
}

public FMCustomer FMCustomer(FMCustomer _relatedTable = null)
{
    if (prmIsDefault(_relatedTable))
    {
        return this.setLink('FMCustomer');
    }
    else
    {
        // Bug 3135762: setLink does not seem to work
        this.Customer = _relatedTable.RecId;
        return this.setLink('FMCustomer', _relatedTable);
    }
}

public FMVehicle FMVehicle(FMVehicle _relatedTable = null)
{
    if (prmIsDefault(_relatedTable))
    {
        return this.setLink('FMVehicle');
    }
    else
    {
        // Bug 3135762: setLink does not seem to work
        this.Vehicle = _relatedTable.RecId;
        this.initFromVehicle();
        return this.setLink('FMVehicle', _relatedTable);
    }
}

public boolean validateField(FieldId _fieldIdToCheck)
{
    boolean ret;

    ret = super(_fieldIdToCheck);

    if(ret)        
    {
        switch (_fieldIdToCheck)
        {
            case fieldnum(FMRental, EndDate):
                if(this.EndDate < this.StartDate) 
                {
                    ret = checkFailed("End date must be after start date");
                }
                break;


            case fieldnum(FMRental, EndMileage):
                if(this.EndMileage != 0 && this.EndMileage < this.StartMileage) 
                {
                    ret = checkFailed("End mileage must be more than the start mileage");
                }
                break;

            case fieldnum(FMRental, StartMileage):
                if(this.StartMileage < 0) 
                {
                    ret = checkFailed("Start mileage cannot be negative");
                }
                break; 

        }
    }

    return ret;
}

public FMVehicleModelRecId getModelForVehicle()
{        
    FMVehicle vehicle; 
    FMVehicleModelRecId value = 0;

    if (this.Vehicle)
    {
        select firstonly vehicle where vehicle.RecId == this.Vehicle;
        if(vehicle)
        {
            value = vehicle.VehicleModel;
        }
    }

    return value; 
}

public void insert()
{
    FMRental rental;
    NumberSeq numberSeq;
    NumberSequenceReference reference;
    ExtendedTypeId edt = extendedtypenum(FMRentalID);

    Microsoft.Dynamics.Application.Instrumentation.FleetManagementEventSource::EventWriteXppTransactionStart("FleetManagement", "Create new reservation");

    if (rental.RentalId == '')
    {
        reference = NumberSequenceReference::findByDatatypeAndScope(edt);
        numberSeq = NumberSeq::newGetNum(reference);
        numberSeq.parmNumTableNum(null).Manual = false;
        this.RentalId = numberSeq.num();
    }

    super();

    Microsoft.Dynamics.Application.Instrumentation.FleetManagementEventSource::EventWriteXppTransactionStop("FleetManagement", "Create new reservation");
}

public display str ReservationTitle()
